import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.DCVnL8g5.js";const h=JSON.parse('{"title":"Introducción y entorno","description":"","frontmatter":{},"headers":[],"relativePath":"full-stack/frontend/nextjs/01-introduccion-y-entorno.md","filePath":"full-stack/frontend/nextjs/01-introduccion-y-entorno.md","lastUpdated":1789040978000,"isDraft":false}'),i={name:"full-stack/frontend/nextjs/01-introduccion-y-entorno.md"};function n(s,e,d,c,l,p){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="introduccion-y-entorno" tabindex="-1">Introducción y entorno <a class="header-anchor" href="#introduccion-y-entorno" aria-label="Permalink to &quot;Introducción y entorno&quot;">​</a></h1><p>Next.js es un <strong>framework de React</strong>: añade enrutado, bundling y formas de renderizar (cliente, servidor, estático) sobre la biblioteca. React solo pinta componentes; Next.js decide <strong>qué URL</strong> corresponde a qué archivo, cómo se empaqueta el código y cómo sale HTML al navegador.</p><p>Si solo necesitas una SPA que consume una API, Vite + React puede bastar (ver <a href="./../react/01-introduccion">Introducción a React</a>). Next.js merece la pena cuando quieres rutas de archivo, SSR/SSG, Route Handlers o un despliegue full-stack sin montar ese andamiaje a mano.</p><p>Documentación oficial: <a href="https://nextjs.org/docs/getting-started/installation" target="_blank" rel="noreferrer">Instalación</a>.</p><h2 id="requisitos" tabindex="-1">Requisitos <a class="header-anchor" href="#requisitos" aria-label="Permalink to &quot;Requisitos&quot;">​</a></h2><ul><li>Node.js <strong>20.9</strong> o superior.</li><li>npm, pnpm, yarn o bun.</li><li>Navegadores modernos (Chrome/Edge/Firefox 111+, Safari 16.4+).</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><h2 id="crear-el-proyecto" tabindex="-1">Crear el proyecto <a class="header-anchor" href="#crear-el-proyecto" aria-label="Permalink to &quot;Crear el proyecto&quot;">​</a></h2><p>La vía soportada es <code>create-next-app</code> (no Create React App):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create-next-app@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mi-app</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mi-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Abre <code>http://localhost:3000</code>. <code>--yes</code> salta las preguntas y aplica los valores por defecto actuales del CLI (TypeScript, ESLint, Tailwind, App Router, alias <code>@/*</code>).</p><p>Durante la instalación puedes elegir:</p><ul><li>TypeScript o JavaScript.</li><li>ESLint, Biome o sin linter.</li><li>Tailwind.</li><li>Carpeta <code>src/</code>.</li><li><strong>App Router</strong> (recomendado) o Pages Router.</li><li>Alias de imports.</li></ul><p>El App Router es el camino por defecto y el que usa este manual. El siguiente capítulo detalla <code>app/</code>, <code>layout.tsx</code> y <code>page.tsx</code>.</p><p>Scripts que deja el CLI:</p><table tabindex="0"><thead><tr><th>Script</th><th>Función</th></tr></thead><tbody><tr><td><code>next dev</code></td><td>Servidor de desarrollo. Turbopack es el bundler por defecto.</td></tr><tr><td><code>next build</code></td><td>Build de producción.</td></tr><tr><td><code>next start</code></td><td>Sirve el build (<code>next start</code> después de <code>next build</code>).</td></tr></tbody></table><h2 id="react-frente-a-next-js" tabindex="-1">React frente a Next.js <a class="header-anchor" href="#react-frente-a-next-js" aria-label="Permalink to &quot;React frente a Next.js&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>React (biblioteca)</th><th>Next.js (framework)</th></tr></thead><tbody><tr><td>Qué resuelve</td><td>UI con componentes</td><td>App: rutas, render, datos, empaquetado</td></tr><tr><td>Entrada típica</td><td><code>createRoot</code> + Vite</td><td><code>create-next-app</code> → carpeta <code>app/</code></td></tr><tr><td>Routing</td><td>Lo eliges tú</td><td>Sistema de ficheros</td></tr><tr><td>Servidor</td><td>Opcional y manual</td><td>Integrado (SSR, Server Components, Route Handlers)</td></tr></tbody></table><p>No hace falta “aprender Next.js en lugar de React”: los componentes, props, estado y JSX son los mismos. Next.js añade convenciones (<code>page.tsx</code>, <code>layout.tsx</code>, Server Components) encima.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Crear la app con <code>create-react-app</code> y “añadir Next después”. Empieza con <code>create-next-app</code>.</li><li>Usar Node 18 u otro runtime por debajo de 20.9.</li><li>Convertir todo a Client Component (<code>&#39;use client&#39;</code>) en el primer archivo. El valor del App Router está en dejar trabajo en el servidor cuando no hay interactividad.</li><li>Copiar la estructura de <code>pages/</code> (Pages Router) en un proyecto App Router.</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>Fija la versión de Next en <code>package.json</code> y actualiza con el flujo oficial (<code>npx next upgrade</code> cuando toque).</li><li>Un proyecto, un router: App <strong>o</strong> Pages como principal, no mezcles por costumbre.</li><li>Deja <code>app/</code> para rutas; extrae UI reutilizable a <code>components/</code> y lógica a <code>lib/</code> (el siguiente capítulo lo desarrolla).</li><li>En desarrollo usa <code>npm run dev</code> y comprueba que el cambio en <code>app/page.tsx</code> recarga.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Genera <code>mi-app</code> con <code>create-next-app</code> y arranca <code>npm run dev</code>.</li><li>Cambia el texto de la home y confirma el HMR.</li><li>Anota si el CLI te creó <code>app/</code> o <code>src/app/</code> y abre el <code>layout</code> raíz: debe incluir <code>html</code> y <code>body</code>.</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continúa con <a href="./02-app-router-y-estructura">App Router y estructura</a>.</p>`,27)])])}const m=a(i,[["render",n]]);export{h as __pageData,m as default};
